{
  "findings": [
    {
      "check_id": "CKV_AWS_157",
      "title": "Ensure that RDS instances have Multi-AZ enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance is not configured for high availability as multi_az is set to false."
    },
    {
      "check_id": "CKV_AWS_16",
      "title": "Ensure all data stored in the RDS is securely encrypted at rest",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have storage encryption enabled."
    },
    {
      "check_id": "CKV_AWS_129",
      "title": "Ensure that respective logs of Amazon Relational Database Service (Amazon RDS) are enabled",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have logging enabled."
    },
    {
      "check_id": "CKV_AWS_226",
      "title": "Ensure DB instance gets all minor upgrades automatically",
      "resource": "aws_db_instance.levelup-rds",
      "severity": "MEDIUM",
      "explanation": "The RDS instance does not have auto minor version upgrades enabled."
    }
  ],
  "patched_code": "resource \"aws_db_instance\" \"levelup-rds\" {\n  identifier = \"${var.ENVIRONMENT}-levelup-rds\"\n  allocated_storage = var.LEVELUP_RDS_ALLOCATED_STORAGE\n  storage_type = \"gp2\"\n  engine = var.LEVELUP_RDS_ENGINE\n  engine_version = var.LEVELUP_RDS_ENGINE_VERSION\n  instance_class = var.DB_INSTANCE_CLASS\n  backup_retention_period = var.BACKUP_RETENTION_PERIOD\n  publicly_accessible = var.PUBLICLY_ACCESSIBLE\n  username = var.LEVELUP_RDS_USERNAME\n  password = var.LEVELUP_RDS_PASSWORD\n  vpc_security_group_ids = [aws_security_group.levelup-rds-sg.id]\n  db_subnet_group_name = aws_db_subnet_group.levelup-rds-subnet-group.name\n  multi_az = \"true\"\n  storage_encrypted = true\n  enabled_cloudwatch_logs_exports = [\"error\", \"general\", \"slowquery\"]\n  auto_minor_version_upgrade = true\n}",
  "fix_summary": "Enabled Multi-AZ for high availability, storage encryption at rest, RDS logging, and auto minor version upgrades for the RDS instance."
}
